begin;
create or replace function public.can_manage_run(target_run uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_staff_or_admin() or exists(select 1 from public.runs r where r.id=target_run and r.host_id=auth.uid()); $$;
create table public.run_teams(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.runs(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 40),sort_order integer not null default 0,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),unique(run_id,name));
create table public.run_team_members(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.runs(id) on delete cascade,run_team_id uuid not null references public.run_teams(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),unique(run_id,profile_id));
create table public.run_games(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.runs(id) on delete cascade,home_run_team_id uuid not null references public.run_teams(id) on delete cascade,away_run_team_id uuid not null references public.run_teams(id) on delete cascade,home_score integer not null default 0 check(home_score between 0 and 250),away_score integer not null default 0 check(away_score between 0 and 250),status text not null default 'scheduled' check(status in ('scheduled','live','completed','cancelled')),played_at timestamptz,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(home_run_team_id<>away_run_team_id));
create or replace function public.validate_run_competition_row() returns trigger language plpgsql set search_path=public as $$ declare team_run uuid; home_run uuid; away_run uuid; begin if tg_table_name='run_team_members' then select run_id into team_run from public.run_teams where id=new.run_team_id; if team_run is distinct from new.run_id then raise exception 'Run team does not belong to this run'; end if; if not exists(select 1 from public.run_players rp where rp.run_id=new.run_id and rp.profile_id=new.profile_id) then raise exception 'Player must join the run before team assignment'; end if; elsif tg_table_name='run_games' then select run_id into home_run from public.run_teams where id=new.home_run_team_id; select run_id into away_run from public.run_teams where id=new.away_run_team_id; if home_run is distinct from new.run_id or away_run is distinct from new.run_id then raise exception 'Both teams must belong to this run'; end if; if new.status='completed' and new.played_at is null then new.played_at:=now(); end if; new.updated_at:=now(); end if; return new; end $$;
drop trigger if exists validate_run_team_member on public.run_team_members; create trigger validate_run_team_member before insert or update on public.run_team_members for each row execute function public.validate_run_competition_row();
drop trigger if exists validate_run_game on public.run_games; create trigger validate_run_game before insert or update on public.run_games for each row execute function public.validate_run_competition_row();
alter table public.run_teams enable row level security; alter table public.run_team_members enable row level security; alter table public.run_games enable row level security;
create policy "run teams public read" on public.run_teams for select using(true); create policy "run team members public read" on public.run_team_members for select using(true); create policy "run games public read" on public.run_games for select using(true); create policy "run hosts manage teams" on public.run_teams for all to authenticated using(public.can_manage_run(run_id)) with check(public.can_manage_run(run_id)); create policy "run hosts manage team members" on public.run_team_members for all to authenticated using(public.can_manage_run(run_id)) with check(public.can_manage_run(run_id)); create policy "run hosts manage games" on public.run_games for all to authenticated using(public.can_manage_run(run_id)) with check(public.can_manage_run(run_id));
grant select on public.run_teams,public.run_team_members,public.run_games to anon,authenticated; grant insert,update,delete on public.run_teams,public.run_team_members,public.run_games to authenticated; grant execute on function public.can_manage_run(uuid) to authenticated; revoke execute on function public.validate_run_competition_row() from public,anon,authenticated;
create index run_teams_run_idx on public.run_teams(run_id,sort_order); create index run_team_members_run_idx on public.run_team_members(run_id,run_team_id); create index run_games_run_idx on public.run_games(run_id,created_at);
commit;
